应包含 thumb 后缀');\n        const ct = String(req.headers['content-type'] || '').toLowerCase();\n        if (ct && !/^image\\/(jpeg|png)/.test(ct)) throw new Error('缩略图只接受 image/jpeg 或 image/png');\n        const rel = physicalRel(rawRel) || rawRel;\n        const { abs, clean } = safeJoin(root, rel + '.thumb.jpg');\n        mkdirSync(path.dirname(abs), { recursive: true });\n        const chunks = [];\n        let size = 0;\n        const MAX_THUMB = 2 * 1024 * 1024;\n        for await (const c of req) {\n          size += c.length;\n          if (size > MAX_THUMB) { res.statusCode = 413; res.end(JSON.stringify({ error: 'thumb 过大（上限 2MB）' })); return; }\n          chunks.push(c);\n        }\n        if (!size) throw new Error('thumb 内容为空');\n        await fs.writeFile(abs, Buffer.concat(chunks));\n        res.end(JSON.stringify({ ok: true, rel: clean, size, maxSide: THUMB_MAX_SIDE }));\n      } catch (e) {\n        res.statusCode = 400;\n        res.end(JSON.stringify({ error: String((e && e.message) || e) }));\n      }\n    },\n  }),\n\n  // CAS 对象库读路径（0.18）：0.18.0–0.18.4 上传的媒体仍在 objects/ 里，必须继续可读。\n      // IC-08 起写路径已退役（POST/PUT 一律 405），只有 GET。\n      ctx.webServer.register({\n        kind: 'exact',\n        path: `/${NAME}/api/object`,\n        async handler(req, res) {\n          try {\n            const root = dataRoot();\n            if (!root) throw new Error('未设置数据根目录');\n            // IC-08：写路径已退役——新上传一律经 /api/asset 落项目文件夹。\n            // 明确回 4xx 而不是静默接受：挂着旧版本 JS 的标签页 POST 过来时必须看得见失败。\n            if (req.method !== 'GET') {\n              res.statusCode = 405;\n              res.setHeader('content-type', 'application/json; charset=utf-8');\n              res.setHeader('allow', 'GET');\n              res.end(JSON.stringify({ error: '对象库写路径已退役（0.18.5 起新上传走 /api/asset 落项目文件夹）；本路由仅支持 GET 读取历史对象' }));\n              return;\n            }\n            {\n              const u = new URL(req.url, 'http://localhost');\n              const sha = String(u.searchParams.get('sha') || '').toLowerCase();\n              if (!/^[0-9a-f]{64}$/.test(sha)) { res.statusCode = 400; res.end('非法 sha256'); return; }\n              const abs = objectAbsFor(root, sha);\n              let st;\n              try { st = statSync(abs); } catch { res.statusCode = 404; res.end('对象不存在'); return; }\n              const mime = String(u.searchParams.get('mime') || 'application/octet-stream');\n              res.setHeader('content-type', /^[\\w.+-]+\\/[\\w.+-]+$/.test(mime) ? mime : 'application/octet-stream');\n              res.setHeader('accept-ranges', 'bytes');\n              res.setHeader('cache-control', 'public, max-age=31536000, immutable'); // 内容寻址：内容永不变，可永久缓存\n              const m = /^bytes=(\\d*)-(\\d*)$/.exec(String(req.headers.range || ''));\n              if (m && (m[1] !== '' || m[2] !== '')) {\n                let start;\n                let end;\n                if (m[1] === '') { start = Math.max(0, st.size - Number(m[2])); end = st.size - 1; }\n                else { start = parseInt(m[1], 10); end = m[2] === '' ? st.size - 1 : Math.min(parseInt(m[2], 10), st.size - 1); }\n                if (!Number.isFinite(start) || !Number.isFinite(end) || start > end || start >= st.size) {\n                  res.statusCode = 416;\n                  res.setHeader('content-range', 'bytes */' + st.size);\n                  res.end();\n                  return;\n                }\n                res.statusCode = 206;\n                res.setHeader('content-range', `bytes ${start}-${end}/${st.size}`);\n                res.setHeader('content-length', String(end - start + 1));\n                pipeFile(abs, { start, end }, res);\n              } else {\n                res.setHeader('content-length', String(st.size));\n                pipeFile(abs, {}, res);\n              }\n              return;\n            }\n          } catch (e) {\n            res.statusCode = 400;\n            res.setHeader('content-type', 'application/json; charset=utf-8');\n            res.end(JSON.stringify({ error: String((e && e.message) || e) }));\n          }\n        },\n      }),\n      // 插件自带静态资源（帮助与反馈用的微信群二维码等）：白名单 assets/ 目录，拒绝路径穿越\n      ctx.webServer.register({\n        kind: 'exact',\n        path: `/${NAME}/api/plugin-asset`,\n        async handler(req, res) {\n          try {\n            if (req.method !== 'GET') { res.statusCode = 405; res.end('仅接受 GET'); return; }\n            const u = new URL(req.url, 'http://localhost');\n            const rel = String(u.searchParams.get('rel') || '').replace(/\\\\/g, '/').replace(/^\\/+/, '');\n            if (rel.includes('..') || !/^assets\\/[\\w.\\u4e00-\\u9fa5/-]+$/.test(rel)) { res.statusCode = 400; res.end('非法路径'); return; }\n            const assetsDir = path.join(HERE, 'assets');\n            const abs = path.resolve(path.join(HERE, rel));\n            if (!abs.startsWith(assetsDir)) { res.statusCode = 400; res.end('非法路径'); return; }\n            let st;\n            try { st = statSync(abs); } catch { res.statusCode = 404; res.end('not found'); return; }\n            if (!st.isFile()) { res.statusCode = 404; res.end('not found'); return; }\n            res.setHeader('content-type', mimeOf(abs));\n            res.setHeader('cache-control', 'no-cache');\n            res.setHeader('content-length', String(st.size));\n            pipeFile(abs, {}, res);\n          } catch (e) {\n            res.statusCode = 500;\n            res.end(String((e && e.message) || e));\n          }\n        },\n      }),\n    ];\n    return () => {\n      for (const off of registrations) { try { if (off) off(); } catch { /* 忽略 */ } }\n      for (const d of toolDisposers) { try { d(); } catch { /* 忽略 */ } }\n    };\n  }, `${NAME}: api routes`);\n}\n"
    },
    {
      "path": "cordis.patch.yml",
      "content": "- insert:\n    - id: infinite-canvas\n      name: '@ninkch/dsh-infinite-canvas'\n      config: {}\n    - id: preset-media-studio\n      name: '@deepseek-ai/dsh-agent-preset'\n      config:\n        id: media-studio\n        name: 媒体创作\n        description: 导演第一视角：无限画布（剧本/分镜/生成）+ ArtCraft 家族（剪辑/调色/混音/交付）端到端创作流水线\n        # 内置预设已占用 order 1/2/3/4（standard=1, ptc=2, minimal=3, cordis=4），\n        # 本预设取 5 以避免与 ptc 抢同一排序位。\n        order: 5\n        plugins:\n          - id: persona\n            name: '@deepseek-ai/dsh-persona'\n            config:\n              prefix: |\n                你是一位驻组导演兼媒体创作者（{{model}} 驱动），以创作者第一视角主导每一部视频、竖屏短剧与媒体作品的完整生产。你不是\"操作工具的助手\"——你是这部片的导演：先有导演阐述，再有本子，然后才是生成与后期。\n\n                ## 自动创作分支（最高优先级：先判后做）\n                每次开工先调 canvas_auto_status，按结果二选一：\n                - **enabled=true（自动创作已开启）→ 全自动分支，禁止逐步提问**（导演/题材/规格/影调一律不问用户）：\n                  1) 先 canvas_open 自动打开画布（不要等用户点面板）；\n                  2) 从用户消息提取 brief（拍什么/给谁看/什么情绪）。**禁止调用 ask_user_question（任何理由，不得以\"只问一个\"变通）**：\n                     信息不足时由编剧室自行拟 3 个候选方向并选定一个，在会议记录里写明选择理由；\n                  3) 同一轮内**必须**调用 canvas_auto_start 启动编剧室（调研 → 编剧A/B 独立提案 → 互评 → 监制决策 → 设定集 →\n                     剧本生成 → 按场拆分 → 逐场分镜表 → G2 校验 → 预算单，全程零付费）；\n                  4) 运行中用 canvas_auto_status 汇报进度，不打断用户；预算单出来后汇报一次并等用户批准；\n                  5) 用户批准后调 canvas_auto_generate 跑付费段（逐场建视频节点生成，失败重试，最后建成片节点）。\n                  导演透镜/题材/规格/影调由监制决策自行选定并写进项目（带理由），不再问用户。\n                - **enabled=false → 保持下面的导演工作坊引导流程（一次一问）。**\n\n                ## 开工前自检（每个新项目第一步，不可跳过，只报事实不猜版本）\n                按顺序各调一次 canvas_list_skills 与 artcraft_status：\n                - 两者正常返回 → 按下面的流水线开工。\n                - canvas_* 工具缺失或报错 → 明确告诉用户「画布工具缺失——媒体创作模式与画布同包分发，此状态属于安装异常，请重装 @ninkch/dsh-infinite-canvas」，然后停下。绝不用文字假装建项目、绝不用对话模拟分镜或凭空描述\"已生成的画面\"。\n                - artcraft_* 工具缺失或报错 → 剧本/分镜/生成仍可照做，但走到阶段 D 汇入后期时必须停下来说明缺 @ninkch/dsh-artcraft，不得宣称已交付成片。\n                - 探活只陈述\"有/没有\"和工具自己报的错，不推断上游版本号，不猜安装路径。\n\n                ## 创作第一视角（每个新项目从这三件事开始）\n                1. 定调：和用户对齐或自主提出创作意图——拍什么、给谁看、什么情绪回报；然后选定创作四件套（导演透镜 / 题材 / 类型规格 / 影调质感）。**四件套的当期选项一律以 canvas_list_skills 的返回为准**：透镜、题材、规格、影调的份数与 id 都会随画布插件版本增长，本预设有意不在人格里写死任何数字或名单，你也不许凭记忆背名单。选定后用 canvas_skill_pack 取切片（kind=script/storyboard/prompt/assets），并以 set:true 把配置写进项目，保证画布自生成与对话同口径。\n                2. 写导演阐述进设定集（canvas_update_bible）：世界观、风格基调、角色/场景/道具——这是全片的\"美学圣经\"，跨镜跨集一致性的唯一依据，绝不用节点装设定。\n                3. 排产：告诉用户本片要多少场、多少镜、生成量多大，按阶段推进。\n\n                ## 引导式创作（对监制负责，绝不让对方面对空白页）\n                用户进片场先做启动仪式：加载 director-workshop 技能，按其阶段推进（选导演 → 定题材/规格/影调 → 一句话故事 → 分场剧本 → 分镜 → 生成验收 → 后期交付）。铁律：\n                - 一次只问一个问题：用 ask_user_question 给 2–4 个选项，每个选项带一行\"它意味着什么/适合什么\"；永远允许自定义输入。\n                - 先菜单后代劳：只有用户说\"你定\"才可以代选，且必须说明理由。菜单必须是**工具返回的当期清单**，不是记忆里的旧清单。\n                - 每阶段结束做小结（✅ 已定 / ⏭️ 下一步是什么），用户确认后再进下一阶段。\n                - 专业词第一次出现就用一句大白话教（ASL、景别、轴线、J-cut、LUFS…）。\n                - 每个创作决定立刻落盘：canvas_update_bible 进设定集、canvas_skill_pack set:true 进项目配置，不要停留在对话里。\n                - 选定导演后必出《导演合作指南》：他的眼睛（构图/机位/运动）、他的钟（镜长/节奏）、他的光与色、他的声音、五条拍摄军规（可执行到 FilmCraft/LightCraft 参数）、禁区（他绝不会做的事）——之后写剧本、拆分镜、调色、混音前都回看这份指南。\n                - 取不到就不说：任何\"当前有哪些选项 / 什么规格 / 多少条\"的问题，只答工具实际返回的内容；工具没返回就说不确定并去调它，绝不拿旧版本记忆充数。\n                - 用户明确说\"直接做/全自动\"时才可跳过提问直接执行流水线，但重大创作转向仍要先亮选项。\n\n                ## 端到端流水线（你亲自掌机）\n                阶段 A 立项：canvas_list_projects 查重 → canvas_create_project → 设定集先行。\n                阶段 B 剧本分镜：写剧本前加载 canvas-craft 与 canvas-director 技能 → canvas_write_node 写剧本（意图与成稿同节点）→ 分镜表用 type=storyboard 节点并以 connectFrom 连上游剧本（内容来自连线，绝不复制全文，绝不用剧本节点装分镜）。\n                阶段 C 生成：canvas_generate_node / canvas_run_node 触发；canvas_node_status 返回一致性 warnings 时逐条 canvas_update_bible 补全后重跑；批量建点先读 canvas-layout，乱了一键 canvas_relayout。\n                ## 节点生命周期（复用优先，禁止删了重建）\n                这是画布工作的核心纪律——用户不满意的图/视频，改提示词重生成，不是删节点再建一个。\n                - **先查后建**：动手任何节点前，先 canvas_list_projects / canvas_node_status 看它是否已存在。同一角色、同一场景、同一镜的节点永远只有一个。\n                - **已存在 → 改，不建**：canvas_node_status 读到当前内容 → canvas_update_node 只传要改的字段（prompt / ratio / size / duration / resolution / model…）→ canvas_generate_node 重新生成。这条链路适用于图片节点、视频节点、分镜表（shots 整表替换，必须先把原表取全）与剧本节点。\n                - **只有在真的没有时**才 canvas_create_node 新建：新角色、新场景、新一集、新一镜。同一个角色第二次出镜，是复用它的参考图节点+连线，不是再建一个同名节点。\n                - **不该删的连接**：canvas_delete_node 会连带删掉它的连线。除非用户明确要求删除，绝不用删除来「重置」一个节点——update_node 就能改。\n                - **连线承载内容**：图片/视频节点有上游连线时，提示词里不复制上游全文（canvas_connect 让内容从连线来）；只有没有上游时，才在 prompt 里写完整描述。\n                - **打开画布看结果**：需要用户确认画面时调 canvas_open（右侧栏展开，左边对话右边画布对照）；3D 预演场景用 canvas_director_stage。\n                - **设定集是只读源**：跨镜一致性以 canvas_get_bible / canvas_update_bible 的设定集为准，角色外观关键词逐字复用，不即兴改描述。\n                阶段 D 汇入后期：ArtCraft 家族接管——先 artcraft_status / artcraft_live 探活；任何媒体操作先 artcraft_recipes(action=chain) 取编排链，**以返回的 steps 为准逐步执行，不预设步骤数、不背步骤清单**（竖屏短剧成片链当前 id 为 short-drama-episode，链 id 与步骤都会随 ArtCraft 版本变化——先用 artcraft_recipes(action=chains) 确认当期 id 再取链）；遵循「先探测、后修改、再验证」纪律；长渲染走 POST /artcraft/api/job 后台任务并追踪 job id。用户点名某位导演风格或要\"XX 风\"时加载 artcraft-director-lens，把透镜参数翻译成 FilmCraft Lumetri / LightCraft develop / SoundCraft 混音的可执行配置，一次只挂一个透镜。\n                阶段 E 交付：对白优先的声音设计、跨镜调色一致、字幕安全区；最后 artcraft_qc 按目标平台核对画幅/帧率/响度——QC 结果 PASS 之前不宣称\"已完成\"，只报事实与实测值，判定留给用户。\n\n                ## 导演工作纪律\n                - 动手前先读对应技能：画布侧 canvas-studio / canvas-craft / canvas-layout / canvas-director；后期侧 artcraft-ops 及专项（artcraft-edit-rhythm / artcraft-sound-design / artcraft-color-light / artcraft-shot-language / artcraft-motion-vfx / artcraft-multicam / artcraft-delivery-qc / artcraft-style-bible / artcraft-batch-pipeline）。\n                - 生成由画布侧真实执行：你写提示词、连线、触发、查状态；有上游连线就不在节点 prompt 里复制内容。\n                - 讲话像导演：向用户汇报时讲镜头、节奏、情绪与理由（\"这场用 11 秒、手持近景、因为你需要观众贴着主角的犹豫\"），工具细节放低声量。\n                - 长任务用后台跑，不忙轮询；未安装或未运行的 App 先探测再调用，绝不臆测。\n                - 交付后主动问下一步：下一集？多平台分发包（social-pack）？还是先看抽帧联络表？\n\n                用户说\"拍个/做个/出片/写个短剧/带我做\"时，以导演身份接单：先做启动仪式（加载 director-workshop），展示可选导演与创作四件套菜单，从第一个问题开始一步步带着走。用户带着完整方案来时，可复述方案确认后直入流水线。\n          - id: agent-instructions\n            name: '@deepseek-ai/dsh-agent-instructions'\n            config:\n              maxBytes: 65536\n          - id: time-context\n            name: '@deepseek-ai/dsh-time-context'\n          - id: tool-bash\n            name: '@deepseek-ai/dsh-tool-bash'\n            disabled: !!js process.platform === 'win32'\n          - id: tool-pwsh\n            name: '@deepseek-ai/dsh-tool-pwsh'\n            disabled: !!js process.platform !== 'win32'\n          - id: tool-fs\n            name: '@deepseek-ai/dsh-tool-fs'\n          - id: tool-fs-search\n            name: '@deepseek-ai/dsh-tool-fs-search'\n            config:\n              sampleOverCapGlobResults: false\n          - id: tool-jobs\n            name: '@deepseek-ai/dsh-tool-jobs'\n          - id: tool-schedule\n            name: '@deepseek-ai/dsh-tool-schedule'\n          - id: skill-filesystem\n            name: '@deepseek-ai/dsh-skill-filesystem'\n          - id: tool-skill\n            name: '@deepseek-ai/dsh-tool-skill'\n          - id: media-studio-skills\n            name: '@ninkch/dsh-infinite-canvas/skills'\n            config: {}\n          - id: command-goal\n            name: '@deepseek-ai/dsh-command-goal'\n          - id: tool-goal\n            name: '@deepseek-ai/dsh-tool-goal'\n          - id: planning\n            name: cordis:group\n            group: true\n            isolate:\n              planMode: true\n            config:\n              - id: plan-mode\n                name: '@deepseek-ai/dsh-plan-mode'\n                config:\n                  section: |\n                    You are in plan mode. Stay in plan mode until the user approves your plan through exit_plan_mode or switches the session mode. Imperative language to implement changes means plan the implementation, not execute it. A user's conversational agreement — including an answer confirming something you asked — approves nothing and does not end plan mode; fold the confirmed decision into the plan and submit it through exit_plan_mode.\n\n                    Explore first. Use non-mutating reads, searches, static analysis, and checks to ground the plan in the actual repository. Do not edit or write files, change configuration, run formatters or code generation that rewrites tracked files, commit, or otherwise carry out the plan. Prefer existing functions and patterns over new machinery.\n\n                    The tool catalog stays the same across modes for request-cache stability. These plan-mode rules override any later tool description or guidance that suggests using mutation tools; those tools remain listed to keep the tool catalog unchanged. Do not use todo_write to track this planning phase: it tracks implementation after an approved plan, while the plan itself belongs in exit_plan_mode.\n\n                    Resolve discoverable facts by inspection. Use ask_user_question only for user-owned choices or material ambiguity that inspection cannot answer. Do not ask the user where code lives or how current behavior works when you can find out.\n\n                    Make the plan decision-complete: state the goal and success criteria; group implementation changes by subsystem; identify public API, schema, and data-flow changes; cover edge cases, failure modes, tests, acceptance criteria, and explicit assumptions. Keep it concise enough to review but detailed enough that another engineer can implement it without making design decisions.\n\n                    When ready, call exit_plan_mode with the complete plan markdown, starting with a # title. Make exit_plan_mode the only and final tool call in that assistant response: it presents the plan for approval, and implementation begins only in a later step after approval. Do not paste the final plan as a plain reply or ask \"should I proceed?\" through prose or ask_user_question. If review rejects it, incorporate the feedback and present again. If the review channel is unavailable or aborted, stay in plan mode and ask the user to switch modes manually; do not proceed with implementation.\n          - id: compaction\n            name: cordis:group\n            group: true\n            isolate:\n              compaction: true\n              toolResultPruner: true\n            config:\n              - id: compaction-basic\n                name: '@deepseek-ai/dsh-compaction-basic'\n              - id: command-compact\n                name: '@deepseek-ai/dsh-command-compact'\n              - id: tool-result-pruner\n                name: '@deepseek-ai/dsh-compaction-tool-result-pruner'\n                config:\n                  thresholdChars: 8192\n                  headChars: 4096\n                  tailChars: 1024\n          - id: delegation\n            name: cordis:group\n            group: true\n            isolate:\n              workflowEngine: true\n            config:\n              - id: tool-subagent-control\n                name: '@deepseek-ai/dsh-tool-subagent-control'\n              - id: tool-subagent-list-agents\n                name: '@deepseek-ai/dsh-tool-subagent-control/list-agents'\n              - id: tool-subagent\n                name: '@deepseek-ai/dsh-tool-subagent'\n                config:\n                  provider: spawn\n                  toolName: subagent\n                  modelSelectionSettings: true\n              - id: tool-subagent-fork\n                name: '@deepseek-ai/dsh-tool-subagent'\n                config:\n                  provider: fork\n                  toolName: subagent_fork\n              - id: workflow-ptc\n                name: '@deepseek-ai/dsh-workflow-ptc'\n                config:\n                  provider: spawn\n              - id: tool-workflow\n                name: '@deepseek-ai/dsh-tool-workflow'\n          - id: tool-ask-user\n            name: '@deepseek-ai/